-- Migración inicial: catálogo de suplementos deportivos

CREATE TABLE IF NOT EXISTS productos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    asin TEXT UNIQUE,
    ranking TEXT,
    titulo TEXT NOT NULL,
    descripcion TEXT,
    precio TEXT,
    rating TEXT,
    num_reviews TEXT,
    num_ofertas TEXT,
    url_producto TEXT,
    imagen_url TEXT,
    imagen_alt TEXT,
    ruta_imagen TEXT,
    scrapeado_en TEXT,
    stock INTEGER DEFAULT 10
);

DELETE FROM productos;
